//! Vectors generated by compiling ASSS 1.4.4 source unmodified (see
//! `fixtures/asss-vectors/`; GPL-derived data).
//!
//! Always checked: for two real configurations, every named setting's bit
//! offset/length agrees with our override keys, our field reads agree with
//! ASSS's, and our settings checksum matches ASSS's `GetChecksum`.
//! With `OSS_ASSS_ZONE_DIR` (an ASSS 1.4.4 zone) and `OSS_SUBGAME_DIR` (a
//! subgame server directory containing `svs.cfg`), the packets are also
//! rebuilt from those configs and compared byte for byte.

use oss_server::clientset::{self, SETTINGS_LEN, SettingsBlock};
use oss_server::config::{ConfigFile, ConfigManager, MemSource, ZoneDir};

const PUBLIC: &str = include_str!("fixtures/asss-vectors/clientset-asss-public.txt");
const SVS: &str = include_str!("fixtures/asss-vectors/clientset-subgame-svs.txt");
const POSITION: &str = include_str!("fixtures/asss-vectors/position-checksum.txt");

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .filter_map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).ok())
        .collect()
}

fn packet(vectors: &str) -> SettingsBlock {
    let hex = vectors
        .lines()
        .find_map(|l| l.strip_prefix("packet "))
        .expect("packet line");
    let bytes: [u8; SETTINGS_LEN] = unhex(hex.trim()).try_into().expect("1428 bytes");
    SettingsBlock::from_bytes(bytes)
}

fn check_layout(vectors: &str) {
    let block = packet(vectors);
    let mut fields = 0;
    let mut sums = 0;
    for line in vectors.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f.as_slice() {
            ["checksum", key, sum] => {
                let key = u32::from_str_radix(key, 16).expect("key");
                let sum = u32::from_str_radix(sum, 16).expect("sum");
                assert_eq!(block.checksum(key), sum, "checksum with key {key:08x}");
                sums += 1;
            }
            ["field", name, off, len, value] => {
                let (sec, key) = name.split_once(':').expect("section:key");
                let off: u32 = off.parse().expect("offset");
                let len: u32 = len.parse().expect("len");
                let value: i64 = value.parse().expect("value");
                let k = clientset::override_key(sec, key)
                    .unwrap_or_else(|| panic!("no override key for {name}"));
                assert_eq!((k.offset(), k.len()), (off, len), "layout of {name}");
                let mask = if len == 32 {
                    u32::MAX
                } else {
                    (1u32 << len) - 1
                };
                assert_eq!(block.get(k), (value as u32) & mask, "value of {name}");
                fields += 1;
            }
            _ => {}
        }
    }
    assert!(
        fields > 800 && sums > 0,
        "{fields} fields, {sums} checksums"
    );
}

#[test]
fn layout_and_checksums_match_asss() {
    check_layout(PUBLIC);
    check_layout(SVS);
    // the quirks: SlowFrameCheck's override key is the byte setting, the
    // ball bits are named Misc:* but loaded from Soccer:*
    let k = clientset::override_key("Misc", "SlowFrameCheck").expect("key");
    assert_eq!((k.offset(), k.len()), (11064, 8));
    let cfg = ConfigFile::from_text("[Soccer]\nDisableWallPass = 1\n");
    let b = clientset::load(&cfg).block;
    let k = clientset::override_key("Misc", "DisableBallThroughWalls").expect("key");
    assert_eq!(b.get(k), 1);
}

#[test]
fn asss_public_arena_packet_is_identical() {
    let Some(dir) = std::env::var_os("OSS_ASSS_ZONE_DIR") else {
        eprintln!("OSS_ASSS_ZONE_DIR not set; skipping");
        return;
    };
    let mut cfg = ConfigManager::new(ZoneDir::new(dir)).expect("zone");
    let arena = cfg.open_arena("(public)").expect("public arena config");
    let ours = clientset::load(&arena).block;
    assert_eq!(ours.as_bytes(), packet(PUBLIC).as_bytes());
}

#[test]
fn subgame_svs_packet_is_identical() {
    let Some(dir) = std::env::var_os("OSS_SUBGAME_DIR") else {
        eprintln!("OSS_SUBGAME_DIR not set; skipping");
        return;
    };
    let svs = std::fs::read(std::path::Path::new(&dir).join("svs.cfg")).expect("svs.cfg");
    let src = MemSource::new([
        ("conf/global.conf", b"".to_vec()),
        ("arenas/svs/arena.conf", svs),
    ]);
    let mut cfg = ConfigManager::new(src).expect("cfg");
    let arena = cfg.open_arena("svs").expect("svs");
    let ours = clientset::load(&arena).block;
    assert_eq!(ours.as_bytes(), packet(SVS).as_bytes());
}

/// The server's position checksum check (XOR of the first 22 bytes is zero)
/// and our S2C 0x05 encoder agree with ASSS.
#[test]
fn position_checksums_match_asss() {
    use oss_proto::Packet;
    use oss_proto::position::S2CWeapon;
    let mut n = 0;
    for line in POSITION.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f.as_slice() {
            ["c2s", hex] => {
                assert_eq!(unhex(hex)[..22].iter().fold(0u8, |a, b| a ^ b), 0);
                n += 1;
            }
            ["c2s_bad", hex] => {
                assert_ne!(unhex(hex)[..22].iter().fold(0u8, |a, b| a ^ b), 0);
                n += 1;
            }
            ["s2c", hex] => {
                let bytes = unhex(hex);
                let w = S2CWeapon::decode(&bytes).expect("weapon");
                assert!(w.checksum_ok());
                let mut re = Vec::new();
                w.encode(&mut re);
                assert_eq!(re[12], bytes[12], "encoder computes ASSS's checksum");
                n += 1;
            }
            _ => {}
        }
    }
    assert!(n > 10);
}

/// The S2C 0x29 map checksum (CRC-32 of the file) matches ASSS for the maps
/// shipped with the ASSS zone.
#[test]
fn map_file_checksums_match_asss() {
    let Some(dir) = std::env::var_os("OSS_ASSS_ZONE_DIR") else {
        eprintln!("OSS_ASSS_ZONE_DIR not set; skipping");
        return;
    };
    let vectors = include_str!("fixtures/asss-vectors/map-checksum.txt");
    let mut n = 0;
    for line in vectors.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        if let ["map", "asss", rel, _name, size, crc] = f.as_slice() {
            let path = std::path::Path::new(&dir).join(rel);
            let d = oss_server::modules::mapnewsdl::load_download(&path, true, false)
                .expect("map loads");
            assert_eq!(d.raw_len, size.parse::<usize>().expect("size"));
            assert_eq!(
                d.checksum,
                u32::from_str_radix(crc, 16).expect("crc"),
                "{rel}"
            );
            n += 1;
        }
    }
    assert!(n >= 1);
}
